(()=>{const A='#cbaea8',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fx-progress{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fx-progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,${A},#fff);box-shadow:0 0 14px ${A}}.fx-cursor{position:fixed;width:260px;height:260px;border-radius:50%;pointer-events:none;z-index:0;transform:translate(-50%,-50%);background:radial-gradient(circle,${A}18,transparent 68%);filter:blur(5px)}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(70px);opacity:.12;z-index:-1}.fx-orb.a{width:280px;height:280px;background:#8c5960;left:-100px;top:20%;animation:drift 12s ease-in-out infinite}.fx-orb.b{width:320px;height:320px;background:#d2a7a0;right:-140px;top:60%;animation:drift 15s ease-in-out infinite reverse}.fx-reveal{opacity:0;transform:translateY(35px) scale(.985);transition:opacity 1s ease,transform 1s cubic-bezier(.2,.8,.2,1)}.fx-reveal.fx-visible{opacity:1;transform:none}.fx-tilt{transform-style:preserve-3d;transition:transform .35s ease,box-shadow .35s ease}.fx-tilt:hover{box-shadow:0 25px 70px #0005}@keyframes drift{50%{transform:translate(80px,-45px)}}@media(max-width:700px){.fx-cursor{display:none}}`;b.appendChild(s);const progress=document.createElement('div');progress.className='fx-progress';progress.innerHTML='<i></i>';b.appendChild(progress);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});const cursor=document.createElement('div');cursor.className='fx-cursor';b.appendChild(cursor);if(!reduce)addEventListener('pointermove',e=>{cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px'});document.querySelectorAll('section').forEach(s=>s.classList.add('fx-reveal'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('fx-visible');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fx-reveal').forEach(e=>io.observe(e));if(!reduce)document.querySelectorAll('.reason-grid article,.memory-card,.letter-paper,.scroll').forEach(card=>{card.classList.add('fx-tilt');card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(700px) rotateX(${y*-5}deg) rotateY(${x*5}deg) translateY(-4px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.firstElementChild.style.width=(max?scrollY/max*100:0)+'%'})})();